#pragma once

#include <OpenModel/Heat2DMesh.hpp>

#include <string>

/**
 * @file Heat2DGmsh.hpp
 * @brief Triangle meshes for Heat2DMesh generated by Gmsh (requires the Gmsh backend: OPENMODEL_BUILD_GMSH_BACKEND).
 *
 * The geometry is built with the Gmsh OpenCASCADE kernel. Boundary edges get tag 1 on the outer circle and tag 2 on the
 * inner circle, so they can be given conditions in MeshModel::boundaries.
 */

namespace OpenModel::Heat2D {

/**
 * @brief Concentric annulus between two circles, meshed with linear triangles.
 * @param outerRadius  R > innerRadius > 0
 * @param innerRadius  a > 0
 * @param size         target element size, > 0 (Gmsh characteristic length)
 * @param error        receives the reason when the mesh cannot be produced; left empty on success
 * @return the mesh; empty when there is an error
 */
TriangleMesh meshAnnulusGmsh(double outerRadius, double innerRadius, double size, std::string& error);

} // namespace OpenModel::Heat2D
